  const setFontFam = v => { setPFontFam(v); try{localStorage.setItem("jtPresentFontFam",v);}catch(e){} };
  const PRES_FONTS = [["Default",""],["Serif","Georgia, serif"],["Elegant","Baskerville, serif"],["Didot","Didot, 'Bodoni 72', serif"],["Optima","Optima, 'Gill Sans', sans-serif"],["Futura","Futura, 'Century Gothic', sans-serif"],["Avenir","'Avenir Next', Avenir, sans-serif"],["Rounded","'SF Pro Rounded', 'Arial Rounded MT Bold', sans-serif"],["Typewriter","'American Typewriter', monospace"],["Copperplate","Copperplate, serif"],["Marker","'Marker Felt', cursive"],["Note","Noteworthy, cursive"],["Script","'Snell Roundhand', cursive"],["Chalk","'Chalkboard SE', sans-serif"],["Papyrus","Papyrus, fantasy"]];
  const [pShadow, setPShadow] = React.useState(() => { try { return localStorage.getItem("jtPresentShadow")||""; } catch(e){ return ""; } });
  const setShadow = v => { setPShadow(v); try{localStorage.setItem("jtPresentShadow",v);}catch(e){} };
  const _bgHex = String(C.bg||"#000000").replace("#","");
  const _isDark = (()=>{ const h=_bgHex.length>=6?_bgHex:"000000"; const r=parseInt(h.slice(0,2),16),g=parseInt(h.slice(2,4),16),b=parseInt(h.slice(4,6),16); return (0.299*r+0.587*g+0.114*b)<140; })();
  const [shadowColor, setShadowColor] = React.useState(() => { try { return localStorage.getItem("jtShadowColor") || (_isDark?"#ffffff":"#000000"); } catch(e){ return "#ffffff"; } });
  const setShadowCol = c => { setShadowColor(c); try{localStorage.setItem("jtShadowColor",c);}catch(e){} };
  const PRES_SHADOWS = [["No shadow",""],["Soft glow","0 0 14px @"],["Strong glow","0 0 26px @"],["Halo","0 0 3px @,0 0 10px @"],["Double glow","0 0 6px @,0 0 22px @"],["3D offset","4px 4px 0 @"],["Drop","3px 5px 9px @"]];
  const shadowCss = pShadow ? pShadow.split("@").join(shadowColor) : undefined;
  const [vKey, setVKey] = React.useState("");
  const refLike = r => /^[1-3]?\s?[A-Za-z][A-Za-z.]*\s+\d+(?::\d+)?(?:\s*[-\u2013]\s*\d+(?::\d+)?)?$/.test(String(r||"").trim());
  React.useEffect(() => { setVKey(""); }, [presentIdx]);
